import Foundation
import Security
enum StorageError: Error { case keychain(OSStatus), invalidToken }
func readSessionToken() throws -> String? {
    let query: [String: Any] = [kSecClass as String: kSecClassGenericPassword,
        kSecAttrService as String: "dev.synapso.journal",
        kSecAttrAccount as String: "session",
        kSecReturnData as String: true,
        kSecMatchLimit as String: kSecMatchLimitOne]
    var result: CFTypeRef?
    let status = SecItemCopyMatching(query as CFDictionary, &result)
    if status == errSecItemNotFound { return nil }
    guard status == errSecSuccess else { throw StorageError.keychain(status) }
    guard let data = result as? Data, let token = String(data: data, encoding: .utf8)
    else { throw StorageError.invalidToken }
    return token
}

Отсутствие — nil. Отказ системной операции и повреждённые байты — разные ошибки; токен не выводится в лог.

